/* Reset and base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #e0e0e0;
  padding: 16px;
}

/* Card */
.card {
  background: #16213e;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  max-width: 600px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  color: #e94560;
  margin-bottom: 4px;
  letter-spacing: 1px;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 24px;
}

/* Switchboard grid */
.switchboard {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

@media (max-width: 480px) {
  .switchboard {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Each switch-lamp pair */
.switch-pair {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.lamp {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #2a2a4a;
  border: 3px solid #3a3a5a;
  transition: background 0.2s, box-shadow 0.2s;
}

.lamp.on {
  background: #e94560;
  border-color: #ff6b81;
  box-shadow: 0 0 12px #e94560, 0 0 24px #e94560;
}

/* Switch button */
.switch {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  border: 2px solid #3a3a5a;
  background: #0f0f1a;
  color: #e0e0e0;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.switch:hover {
  background: #1a1a2e;
  border-color: #e94560;
}

.switch:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.switch:active {
  transform: scale(0.95);
}

.switch[aria-pressed="true"] {
  background: #e94560;
  border-color: #ff6b81;
  color: #fff;
}

/* Controls */
.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.btn {
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid #e94560;
  border-radius: 8px;
  background: transparent;
  color: #e94560;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, transform 0.1s;
}

.btn:hover {
  background: #e94560;
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.95);
}

/* Counter */
.counter {
  font-size: 1.2rem;
  font-weight: 600;
  color: #a0a0b0;
}

.counter span {
  color: #e94560;
  font-size: 1.4rem;
}

(function () {
  'use strict';

  const switchboard = document.getElementById('switchboard');
  const allOnBtn = document.getElementById('allOn');
  const allOffBtn = document.getElementById('allOff');
  const onCountEl = document.getElementById('onCount');

  const NUM_SWITCHES = 8;
  const switches = [];

  // Create switches and lamps
  for (let i = 0; i < NUM_SWITCHES; i++) {
    const pair = document.createElement('div');
    pair.className = 'switch-pair';

    const lamp = document.createElement('div');
    lamp.className = 'lamp';
    lamp.id = 'lamp-' + i;

    const btn = document.createElement('button');
    btn.className = 'switch';
    btn.id = 'switch-' + i;
    btn.textContent = String(i + 1);
    btn.setAttribute('aria-pressed', 'false');
    btn.setAttribute('aria-label', 'Switch ' + (i + 1));

    btn.addEventListener('click', function () {
      toggleSwitch(i);
    });

    pair.appendChild(lamp);
    pair.appendChild(btn);
    switchboard.appendChild(pair);

    switches.push({ lamp: lamp, btn: btn, on: false });
  }

  function toggleSwitch(index) {
    const sw = switches[index];
    sw.on = !sw.on;
    updateVisuals();
  }

  function updateVisuals() {
    let count = 0;
    switches.forEach(function (sw) {
      if (sw.on) {
        sw.lamp.classList.add('on');
        sw.btn.setAttribute('aria-pressed', 'true');
        count++;
      } else {
        sw.lamp.classList.remove('on');
        sw.btn.setAttribute('aria-pressed', 'false');
      }
    });
    onCountEl.textContent = count;
  }

  function setAll(state) {
    switches.forEach(function (sw) {
      sw.on = state;
    });
    updateVisuals();
  }

  allOnBtn.addEventListener('click', function () {
    setAll(true);
  });

  allOffBtn.addEventListener('click', function () {
    setAll(false);
  });

  // Initialize
  updateVisuals();
})();
